import sys

def binary_search():
    lines = sys.stdin.read().strip().split('\n')
    if not lines or not lines[0].strip():
        print(-1)
        return
    nums = [int(x) for x in lines[0].split()]
    target = int(lines[1].strip())

    # TODO: Implement while-loop binary search
    left, right = 0, len(nums) - 1
    ans = -1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            ans = mid
            break
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    print(ans)

if __name__ == '__main__':
    binary_search()

